from pathlib import Path
import json
R=Path('artifacts/ux21-final-verification')
m=json.loads((R/'manifest.json').read_text())
base={
'01-navigation':'Улучшение: компактная общая навигация оставляет больше места содержимому; четыре раздела и вложенные представления доступны.',
'02-tasks':'Улучшение компоновки: список и группы поднялись выше, название и даты читаются; назначение сценария сохранено.',
'03-projects':'Улучшение: статус и фактический прогресс разделены, даты экземпляра заметнее. Верхняя карточка проекта остаётся высокой.',
'04-calendar':'Улучшение видимой области календаря: компактная шапка и заметные фильтры. События, выбранная дата и календарный контекст сохранены.',
'05-recurrence':'Улучшение: понятнее название операции, нейтральная справка и подтверждение рядом с результатом. Расчёт повторений остаётся серверным.',
'06-templates':'Улучшение: настройка и результат отделены, конкретнее подтверждение. Структура задач и относительные даты доступны.',
'07-attention':'Улучшение: одно основное действие на карточке, остальные в меню. Причины внимания и отдельные пропуски сохранены.',
'08-icons':'Улучшение распознавания: видимые русские подписи и выбранное название. Поиск, категории, цвет и собственные изображения сохранены.',
'09-errors':'Ожидаемая ошибка воспроизведена; сообщение и введённые значения видны. Отсутствует неожиданное необработанное исключение.',
'10-settings':'Улучшение: годы производственного календаря видны сразу; собственные изображения вынесены в подраздел «Оформление».'}
notes={}
for x in m:
 id=x['original_id'];note={'comparison':base[x['category']], 'issues':[]}
 if 'editor' in id or 'history' in id or 'period' in id:
  if x['category']=='02-tasks':note['comparison']='Редактор и раскрываемые разделы сохранены; рабочие периоды и история не требуют дублирующего заголовка/второй кнопки загрузки. Сводка параметров стала компактнее.'
 if id in ['task-actions','task-reschedule','task-move-project','task-complete-children','task-cancel-confirm','task-unsaved-changes','task-completion-date','work-period-reschedule','project-menu','project-editor','project-dates','project-complete','project-cancel','project-archive']:
  note['comparison']='Сценарий сохранён; диалог имеет понятное имя, необходимый контекст и конкретную подпись подтверждения. Нового визуального блокера на снимке не обнаружено.'
 if id in ['task-editor-basic','responsive-editor-390','responsive-editor-360','calendar-task-editor']:
  note['comparison']='Частичное улучшение: основные поля компактнее, но подзадачи и действия шаблона всё ещё отодвигают историю ниже первого экрана.';note['issues']=['RV-03']
 if id in ['project-detail','project-large','project-two-tasks','nav-projects','project-partially-completed']:
  note['issues']=['RV-02'];note['comparison']='Даты и прогресс понятнее, но верхняя карточка и полосы действий всё ещё занимают много высоты. В project-detail первая задача начинается около 729 px.'
 if id in ['calendar-day-dense','calendar-day-time-overlap']:
  note['comparison']='Смешанный результат: расписание сразу рядом с задачами без времени; у пяти пересекающихся событий названия сильнее обрезаны, чем в прежней широкой временной сетке.';note['issues']=['RV-01','RV-04']
 if id in ['calendar-week-dense','calendar-more','calendar-day-exact-15','responsive-calendar-390','responsive-calendar-360']:
  note['comparison']='Расписание больше не вытесняется полным списком. Ограниченная внутренняя прокрутка безвременных задач неочевидна; счётчик «Ещё» не равен числу строк вне видимой области.';note['issues']=['RV-04']
 if id.startswith('icon-category-') or id in ['icon-catalog','icon-search-cleaning','icon-selected-color']:
  note['issues']=['RV-05']
 if id.startswith('custom-icons') or id=='icon-upload-rejected':note['equivalence']='Те же тестовые изображения и операция, но после UX 2.1 путь проходит через Настройки → Оформление; блок календаря здесь намеренно отсутствует.'
 if id in ['calendar-reset-filters']:
  note['comparison']='Исправление подтверждено: после сброса закрытые события снова скрыты, как в исходном состоянии по умолчанию; отдельное «Показать все» доступно.'
  note['equivalence']='Одинаковый месяц и команда сброса. Набор видимых событий намеренно отличается: исправлена семантика сброса, это не потеря данных.'
 if id=='template-create-unhandled-error':
  note={'comparison':'DEF-01 не воспроизводится: при закрытии изменённой формы появляется защита черновика; продолжение сохраняет выбранную дату. Реальное создание и повтор команды проверены API.', 'issues':[], 'equivalence':'Адаптированный сценарий: прежнее ошибочное закрытие заменено защитным диалогом. Дополнительная фикстура «Генеральная уборка», дата 30.11.2026; это проверка той же операции, а не попиксельно равное состояние старой формы.'}
 if id=='task-history-details':note['equivalence']='Тот же тестовый проект и задача, снимок повторно сделан после основного обхода из-за неоднозначного селектора теста. В истории уже есть завершение подзадачи из последующего шага. Компоновка сравнима, состав событий не полностью эквивалентен.'
 if id=='work-period-completed-task-open':note['equivalence']='Та же операция завершения периода без завершения задачи. В новом снимке дождались исчезновения уведомления; контекст уведомлений отдельно проверен в fix-verification/evidence.json.'
 if id in ['task-history','project-history','series-history-events','task-long-history']:
  note['comparison']='История загружается при явном открытии; записи и раскрытие подробностей доступны. Прежняя дополнительная кнопка загрузки первого блока больше не нужна.'
 if id in ['tasks-loading','tasks-api-unavailable','required-title','invalid-completion-date','task-xss-literal']:
  note['comparison']='Контрольное состояние воспроизведено и доступно для сравнения; существенного изменения самого сообщения не требуется. Общая шапка стала компактнее.'
 notes[id]=note
(R/'checks/comparison-notes.json').write_text(json.dumps(notes,ensure_ascii=False,indent=2))
fixdata=[
('DEF-01','Подтверждено','Закрытие изменённой формы через Escape, крестик и навигацию вызывает защиту; продолжение сохраняет дату. API: один проект, начало 30.11, подзадача 01.12, правильный родитель; повтор того же request_id возвращает тот же проект.',''),
('UX-01','Частично подтверждено','Задачи: первая строка 630 → 347 px. Месяц: верх панели 519 → 336 px. Слоган и лишняя вертикаль убраны.','RV-02: внутри карточки проекта первая задача всё ещё около 729 px.'),
('UX-02','Частично подтверждено','20 задач без времени ограничены отдельным блоком; временное расписание остаётся в первом экране, есть переход к времени.','RV-01: пять одновременных событий в дне теряют читаемость названий. RV-04: внутренняя прокрутка неочевидна.'),
('UX-03','Подтверждено','У одноимённых повторяющихся проектов показаны разные даты начала, статус и прогресс. Дата окончания не выдумывается.',''),
('UX-04','Частично подтверждено','Основные поля уплотнены, параметры имеют сводку, подзадачи расположены раньше, сохранение закреплено.','RV-03: история сложной задачи всё ещё ниже первого экрана, особенно на 360–390 px.'),
('UX-05','Подтверждено','Одно основное действие и меню дополнительных команд. Рассмотрение, перенос и отложенное напоминание проходят через прежний API.',''),
('UX-06','Подтверждено','Подтверждения называют действие: отменить задачу, пропустить выполнение, прекратить повторение; последствия показаны.',''),
('UX-07','Подтверждено','После предпросмотра виден результат «Было → Станет» и подтверждение рядом; изменение настроек лишает старый preview силы, 409 сохраняет черновик.',''),
('UX-08','Подтверждено','Ожидающее выполнение отделено от ещё не созданного следующего. Новая дата отсчёта и конфликт старого выполнения описаны человеческим языком.','Технические сведения остаются в подробной истории; это допустимое исключение.'),
('UX-09','Подтверждено','Пропущенный наполовину выполненный проект показывает 50%, а не 100%. Пустой завершённый проект без ложных 0%; выполнено/отменено/пропущено по одной из трёх — 33%.',''),
('UX-10','Подтверждено','Финансового поиска в Планах нет; финансовый раздел остаётся доступен.',''),
('UX-11','Частично подтверждено','Даты и статусы в списках читаются лучше, визуальный фокус заметен.','RV-01: обрезка важного названия в плотной сетке снижает практическую читаемость. Полный аудит WCAG не проводился.'),
('UX-12','Подтверждено','Каждая иконка подписана, выбранное название видно, категории и русский поиск сохранены.','RV-05: раскрытый выбор занимает почти всю панель; задача уходит ниже первого экрана.'),
('UX-13','Подтверждено','Настройки разделены на производственный календарь и оформление; загруженные годы видны без прокрутки через иконки.',''),
('UX-14','Подтверждено','Сброс возвращает значения по умолчанию; закрытые события не включаются. Для них есть «Показать все».',''),
('UX-15','Подтверждено','Повторный заголовок периодов работы убран, редакторы заготовок и истории не требуют дублирующей команды открытия.',''),
('UX-16','Подтверждено','При явном открытии истории задачи, проекта и повторения записи появляются сразу; подробности и дальнейшая загрузка сохранены.',''),
('UX-17','Подтверждено','Нейтральные пояснения повторений не выглядят жёлтой тревогой; реальные конфликты и ограничения выделены отдельно.',''),
('UX-18','Подтверждено','На 390 px первая задача около 394 px, на 360 — 430 px. Четыре раздела доступны, редактор полноэкранный, горизонтального переполнения документа не найдено.','В плотном календаре и сложном редакторе остаются RV-01/RV-03/RV-04.'),
('UX-19','Подтверждено','Диалоги имеют доступные имена; Tab остаётся внутри, Escape учитывает черновик, фокус возвращается на существующий инициатор.','Автоматическая проверка и клавиатура Chromium; не сертификация всех экранных дикторов.'),
('UX-20','Подтверждено','Успех называет объект; после переноса «Стрижки» на 24.11 и открытия «Купить продукты» старое сообщение исчезает. API подтверждает дату.','')]
fixes={id:{'result':res,'difference':diff,'residual':residual} for id,res,diff,residual in fixdata}
(R/'checks/fix-notes.json').write_text(json.dumps(fixes,ensure_ascii=False,indent=2))
(R/'checks/gap-resolution.json').write_text(json.dumps({'task-history-details':{'resolved':True,'method':'recover.spec.cjs; .pl-history.last(); original fixture database','limitation':notes['task-history-details']['equivalence']},'template-create-unhandled-error':{'resolved':True,'method':'adapted DEF-01 regression; original error no longer reproduced'}},ensure_ascii=False,indent=2))
